using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
namespace EternalSteam.Tests{
[Category("CurrentScene")]
public sealed class ConstructionHudWorkflowTests{
[TestCase(800,600)] [TestCase(1920,1080)] [TestCase(2560,1440)]

public void SavedConstructionSummaryAndActionsStaySeparate(int width,int height){var scene=CurrentSceneFixture.Open();var name=scene.name;try{var h=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<CanvasWorldHud>(true)).Single();var l=h.Layout;h.GetComponent<UnityEngine.UI.CanvasScaler>().enabled=false;l.Canvas.renderMode=RenderMode.WorldSpace;l.Canvas.enabled=false;l.Root.localScale=Vector3.one;float scale=Mathf.Sqrt(width/1920f*height/1080f);l.Canvas.scaleFactor=scale;l.Root.sizeDelta=new Vector2(width/scale,height/scale);l.InventoryBody.gameObject.SetActive(true);l.Apply(true);if(l.CompactDock!=null)((RectTransform)l.CompactDock.Placement.transform).anchoredPosition=Vector2.zero;Assert.That(l.ConstructionSummary,Is.Not.Null);var scroll=l.ConstructionSummary.GetComponent<UnityEngine.UI.ScrollRect>();Assert.That(scroll.viewport.GetComponent<UnityEngine.UI.Mask>(),Is.Not.Null);Assert.That(scroll.content.IsChildOf(scroll.viewport),Is.True);Assert.That(h.Texts.Single(t=>t.Id=="construction-summary").View.transform.IsChildOf(scroll.content),Is.True);Rect B(RectTransform item){var corners=new Vector3[4];item.GetWorldCorners(corners);var a=l.Root.InverseTransformPoint(corners[0]);var b=l.Root.InverseTransformPoint(corners[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}foreach(var id in new[]{"confirm","cancel"}){var b=h.Buttons.Single(v=>v.Id==id).View;Assert.That(b.onClick.GetPersistentTarget(0),Is.SameAs(h));Assert.That(b.onClick.GetPersistentMethodName(0),Is.EqualTo("Execute"));var r=B((RectTransform)b.transform);Assert.That(r.Overlaps(B(l.ConstructionSummary)),Is.False);Assert.That(r.yMin,Is.GreaterThanOrEqualTo(B(l.ConstructionBar).yMin));Assert.That(r.xMax,Is.LessThanOrEqualTo(B(l.ConstructionBar).xMax));}Assert.That(B(l.ConstructionSummary).Overlaps(B(l.InventoryBody)),Is.False);Assert.That(h.Catalog.Where(c=>c.Definition!=null).GroupBy(c=>c.Definition.Id).All(g=>g.Count()==1),Is.True);Assert.That(h.ShowDevelopmentControls,Is.True);}finally{CurrentSceneFixture.Close(scene);}}
}}
